function incrementDigits(digits: number[]): number[] {
  const out: number[] = [];
  let carry = 1;
  for (let i = digits.length - 1; i >= 0; i--) {
    const s = digits[i] + carry;
    out.push(s % 10);
    carry = Math.floor(s / 10);
  }
  if (carry) out.push(carry);
  return out.reverse();
}

