class Solution:
    def incrementDigits(self, digits: List[int]) -> List[int]:
        out, carry = [], 1
        for d in reversed(digits):
            carry, v = divmod(d + carry, 10)
            out.append(v)
        if carry:
            out.append(carry)
        return out[::-1]

